var imageLookup = null;
fetch("https://raw.githubusercontent.com/ByMykel/counter-strike-image-tracker/main/static/images.json").then((r) => r.json()).then((data) => {
	imageLookup = data;
	console.log("CS2 image lookup loaded:", Object.keys(data).length, "entries");
}).catch((err) => {
	console.log("Could not load CS2 image lookup:", err.message);
});
function createCSGOImage(urlEndpath) {
	if (!urlEndpath) return "";
	if (imageLookup) {
		const direct = imageLookup[urlEndpath];
		if (direct) return direct;
		const stripped = imageLookup[urlEndpath.replace(/_large$/, "")];
		if (stripped) return stripped;
	}
	return "";
}
