//#region src/renderer/store/actions/userStatsActions.tsx
var signIn = (forwardPackage) => {
	return {
		type: "SIGN_IN",
		payload: forwardPackage
	};
};
var signOut = () => {
	return { type: "SIGN_OUT" };
};
var setConnection = (connectionStatus) => {
	return {
		type: "SET_CONNECTION",
		payload: { hasConnection: connectionStatus }
	};
};
var setWalletBalance = (walletBalance) => {
	return {
		type: "SET_WALLET_BALANCE",
		payload: walletBalance
	};
};
var setGC = (connectionStatus) => {
	return {
		type: "SET_GC",
		payload: { CSGOConnection: connectionStatus }
	};
};
//#endregion
//#region src/renderer/store/handleMessage.tsx
async function handleUserEvent(message, settings) {
	const statusCode = message[0];
	const description = message[1];
	switch (statusCode) {
		case 1:
			const subMessage = message[2];
			return setInventoryAction({
				inventory: subMessage[1],
				combinedInventory: await combineInventory(subMessage[1], settings)
			});
		case 2:
			if (description == "disconnected") return setConnection(false);
			if (description == "reconnected") return setConnection(true);
			if (description == "fatalError") return signOut();
			return;
		case 3: if (description == "disconnectedFromGC") return setGC(false);
		else return setGC(true);
		case 4: return setWalletBalance(description);
		default: return;
	}
}
